--[[
 TRUONG CODER HD | V4.8 - FRUIT NOTIFY FIX + V4.3 FEATURES
 Discord island + confirmed inventory change + new-fruit alerts (with images), 4 ESP tags, Speed/Jump, Noclip, NPC Auto Attack & Water Walk.
 Your photo is embedded in this single file as a local GUI logo.
 No Auto Quest/Teleport/Fly/Auto Levi. Attack only targets nearby NPCs.
 Adjustable speed and jump may be overridden by the game server.

 SECURITY: The webhook is NEVER included in public code.
 If file APIs are available, settings are saved locally in plain text
 to TC_ESP_WATCH_SETTINGS.json. Do not share that settings file.
 This is a client-side best-effort script. Server/client streaming can
 limit which islands, fruits and NPCs can be detected.
]]

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local TweenService = game:GetService("TweenService")
local HttpService = game:GetService("HttpService")
local StarterGui = game:GetService("StarterGui")
local LocalPlayer = Players.LocalPlayer
if not LocalPlayer then return end
local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")

local GLOBAL = ((type(getgenv) == "function") and getgenv()) or _G
if type(GLOBAL.__TC_ESP_WATCH_STOP) == "function" then
    pcall(GLOBAL.__TC_ESP_WATCH_STOP)
end
local PREVIOUS = PlayerGui:FindFirstChild("TC_ESP_WATCH_V1")
if PREVIOUS then PREVIOUS:Destroy() end

local GUI_NAME = "TC_ESP_WATCH_V1"
local CONFIG_FILE = "TC_ESP_WATCH_SETTINGS.json"
local LOGO_FILE = "TC_ESP_WATCH_LOGO.jpg"

local S = {
    espIslands = true,
    espNPC = false,
    espPlayers = false,
    espFruits = false,
    noclip = false,
    speedEnabled = false,
    walkSpeed = 32,
    jumpEnabled = false,
    jumpPower = 80,
    waterWalk = false,
    autoAttack = false,
    attackMode = "Auto",
    attackRange = 28,
    attackDelayMs = 400,
    autoDiscord = true,
    autoFruitDiscord = true, -- Thong bao khi so luong trai trong kho tang
    autoFoundFruitDiscord = true, -- Mac dinh BAT: bao khi trai moi vao balo
    fruitMentionEveryone = false,
    webhook = "",
    robloxLogoId = "",
    miniX = 16,
    miniY = 240,
    hubX = 0.5,
    hubY = 0.5,
}

local running = true
local connections = {}
local markers = {}
local alerted = {}
local collisionOriginal = setmetatable({}, {__mode="k"})
local previousCharacter = nil
local uiReady = false
local scanning = false
local statusLabel
local saveLabel
local espCounter
local islandCounter
local lastFoundEvent = "Chua phat hien"
local activeEvents = {}
local logoAsset = nil
local logoInfo = "Anh goc chua tai duoc"
local screen, hub, mini

local function on(connection)
    table.insert(connections, connection)
    return connection
end

local function color(r,g,b) return Color3.fromRGB(r,g,b) end
local T = {
    background=color(6,11,25),
    surface=color(13,23,42),
    surface2=color(21,35,58),
    surface3=color(31,48,75),
    cyan=color(79,215,255),
    violet=color(167,121,255),
    yellow=color(255,214,113),
    mint=color(105,241,186),
    rose=color(255,126,156),
    text=color(234,246,255),
    muted=color(154,179,204),
}

local function status(message, success)
    if statusLabel and statusLabel.Parent then
        statusLabel.Text = tostring(message)
        statusLabel.TextColor3 = success == false and T.rose or T.mint
    end
    print("[TC ESP]", tostring(message))
end

local function notice(title, body)
    pcall(function()
        StarterGui:SetCore("SendNotification", {
            Title=title, Text=body, Duration=8
        })
    end)
end

local function saveConfig(showMessage)
    if type(writefile) ~= "function" then
        if showMessage then status("Delta khong co writefile - chua the luu vinh vien", false) end
        if saveLabel then
            saveLabel.Text = "KHONG HO TRO LUU FILE - se mat khi thoat game"
            saveLabel.TextColor3 = T.rose
        end
        return false
    end
    local safe = {}
    for k,v in pairs(S) do safe[k] = v end
    local ok,err = pcall(function()
        writefile(CONFIG_FILE, HttpService:JSONEncode(safe))
    end)
    if saveLabel then
        saveLabel.Text = ok and "DA LUU TREN THIET BI" or "LUU FILE THAT BAI"
        saveLabel.TextColor3 = ok and T.mint or T.rose
    end
    if showMessage then
        status(ok and "Da luu cai dat + webhook tren thiet bi" or
            ("Loi luu: "..tostring(err)), ok)
    end
    return ok
end

local function loadConfig()
    if type(readfile) ~= "function" then return false end
    local ok,loaded = pcall(function()
        local raw = readfile(CONFIG_FILE)
        return HttpService:JSONDecode(raw)
    end)
    if not ok or type(loaded) ~= "table" then return false end
    for k,default in pairs(S) do
        if type(loaded[k]) == type(default) then
            S[k] = loaded[k]
        end
    end
    S.miniX = math.clamp(S.miniX, 0, 3000)
    S.miniY = math.clamp(S.miniY, 0, 3000)
    S.hubX = math.clamp(S.hubX, 0.08, 0.92)
    S.hubY = math.clamp(S.hubY, 0.08, 0.92)
    S.walkSpeed = math.clamp(math.floor(S.walkSpeed + 0.5), 16, 160)
    S.jumpPower = math.clamp(math.floor(S.jumpPower + 0.5), 50, 200)
    S.attackRange = math.clamp(math.floor(S.attackRange + 0.5), 8, 55)
    S.attackDelayMs = math.clamp(math.floor(S.attackDelayMs / 50 + 0.5) * 50, 200, 1500)
    if S.attackMode ~= "Auto" and S.attackMode ~= "Melee" and S.attackMode ~= "Sword" and S.attackMode ~= "Gun" then
        S.attackMode = "Auto"
    end
    return true
end

local wasLoaded = loadConfig()
-- V4.8: Force both user-requested fruit alerts ON on upgrade.
-- They can still be disabled from the Webhook page after startup.
S.autoFruitDiscord = true
S.autoFoundFruitDiscord = true
-- IMPORTANT: Old saved settings from V1 may have every ESP category ON.
-- Force these OFF even if the old config says true, but retain saved webhook,
-- Noclip, logo and button positions. Never render ordinary island labels.
S.espNPC = false
S.espPlayers = false
S.espFruits = false
if wasLoaded then saveConfig(false) end

