local function decodeBase64(encoded)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local out,buffer,bits = {},0,0
    for i=1,#encoded do
        local ch = encoded:sub(i,i)
        if ch == "=" then break end
        local index = alphabet:find(ch,1,true)
        if index then
            buffer = buffer*64 + (index-1)
            bits = bits+6
            if bits >= 8 then
                bits = bits-8
                local byte = math.floor(buffer/(2^bits))
                out[#out+1] = string.char(byte)
                buffer = buffer%(2^bits)
            end
        end
    end
    return table.concat(out)
end

local function resolveLogo()
    -- Preferred: the private screenshot embedded in this Lua file.
    local assetFn = (type(getcustomasset)=="function" and getcustomasset)
        or (type(getsynasset)=="function" and getsynasset)
    if type(writefile)=="function" and assetFn then
        local ok,asset = pcall(function()
            writefile(LOGO_FILE,decodeBase64(LOGO_B64))
            return assetFn(LOGO_FILE)
        end)
        if ok and type(asset)=="string" and asset~="" then
            logoInfo = "Anh anh gui: da su dung qua file cuc bo"
            return asset
        end
    end
    -- If Delta cannot use local image files, user may paste Roblox decal ID.
    if S.robloxLogoId ~= "" then
        logoInfo = "Dang dung Roblox Decal ID"
        return "rbxassetid://"..S.robloxLogoId
    end
    logoInfo = "Delta chua ho tro anh cuc bo - dung logo TC du phong"
    return nil
end

logoAsset = resolveLogo()

local function create(className,parent,properties)
    local obj=Instance.new(className)
    for key,value in pairs(properties or {}) do obj[key]=value end
    obj.Parent=parent
    return obj
end

local function corners(obj,radius)
    create("UICorner",obj,{CornerRadius=UDim.new(0,radius or 10)})
    return obj
end

local function border(obj,c,thickness,transparency)
    return create("UIStroke",obj,{
        Color=c or T.cyan,
        Thickness=thickness or 1,
        Transparency=transparency or 0.45
    })
end

local function label(parent,str,size,c,bold)
    return create("TextLabel",parent,{
        BackgroundTransparency=1,
        Text=tostring(str or ""),
        TextSize=size or 12,
        TextColor3=c or T.text,
        Font=bold==false and Enum.Font.Gotham or Enum.Font.GothamBold,
        TextXAlignment=Enum.TextXAlignment.Left,
        TextYAlignment=Enum.TextYAlignment.Center,
        TextWrapped=true,
        BorderSizePixel=0
    })
end

local function button(parent,str,c)
    return corners(create("TextButton",parent,{
        BackgroundColor3=c or T.surface3,
        Text=tostring(str),
        TextColor3=T.text,
        TextSize=12,
        Font=Enum.Font.GothamBold,
        BorderSizePixel=0,
        AutoButtonColor=true,
        Size=UDim2.new(1,0,0,39)
    }),9)
end

local function iconImage(parent,size)
    local holder=corners(create("Frame",parent,{
        Size=UDim2.fromOffset(size,size),
        BackgroundColor3=T.surface3,
        BorderSizePixel=0,
        ClipsDescendants=true
    }),math.floor(size*.25))
    border(holder,T.cyan,1.2,0.25)
    local placeholder=label(holder,"TC",math.max(13,math.floor(size*.39)),T.cyan)
    placeholder.Size=UDim2.fromScale(1,1)
    placeholder.TextXAlignment=Enum.TextXAlignment.Center
    if logoAsset then
        create("ImageLabel",holder,{
            BackgroundTransparency=1,
            Image=logoAsset,
            Size=UDim2.fromScale(1,1),
            ScaleType=Enum.ScaleType.Crop,
        })
    end
    return holder
end

local function rootPart()
    local character=LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

local function objectPosition(obj)
    if not obj or not obj.Parent then return nil end
    local ok,result=pcall(function()
        if obj:IsA("BasePart") then return obj.Position end
        if obj:IsA("Attachment") then return obj.WorldPosition end
        if obj:IsA("CFrameValue") then return obj.Value.Position end
        if obj:IsA("Vector3Value") then return obj.Value end
        if obj:IsA("Model") then return obj:GetPivot().Position end
        if obj:IsA("Folder") or obj:IsA("Tool") then
            local part=obj:FindFirstChildWhichIsA("BasePart",true)
            return part and part.Position
        end
    end)
    return ok and result or nil
end

local function objectPart(obj)
    if not obj or not obj.Parent then return nil end
    if obj:IsA("BasePart") then return obj end
    if obj:IsA("Attachment") then
        return obj.Parent and obj.Parent:IsA("BasePart") and obj.Parent or nil
    end
    if obj:IsA("Model") then
        return obj.PrimaryPart or obj:FindFirstChild("HumanoidRootPart")
            or obj:FindFirstChildWhichIsA("BasePart",true)
    end
    if obj:IsA("Tool") or obj:IsA("Folder") then
        return obj:FindFirstChildWhichIsA("BasePart",true)
    end
    return nil
end

local function distance(position)
    local root=rootPart()
    if not root or not position then return nil end
    return math.floor((root.Position-position).Magnitude)
end

local function positionString(pos)
    if not pos then return "Chua ro" end
    return string.format("X %.0f | Y %.0f | Z %.0f",pos.X,pos.Y,pos.Z)
end

