-- V4.6: stored-fruit versions of the neon posters, retaining the original art.
local STORED_FRUIT_POSTERS={
    stored_hellfire=[==[

]==],
    stored_generic=[==[

]==]
}

local posterCache={}
local b64chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local b64map={}
for n=1,#b64chars do
    b64map[b64chars:sub(n,n)]=n-1
end
local function decodePoster(eventId)
    if posterCache[eventId] then return posterCache[eventId] end
    local source=POSTER_BASE64[eventId] or FRUIT_NEON_POSTERS[eventId] or STORED_FRUIT_POSTERS[eventId]
    if not source then return nil end
    local s=source:gsub("%s+","")
    local out={}
    local counter=0
    for i=1,#s,4 do
        local a=b64map[s:sub(i,i)]
        local b=b64map[s:sub(i+1,i+1)]
        local c=b64map[s:sub(i+2,i+2)]
        local d=b64map[s:sub(i+3,i+3)]
        if a==nil or b==nil then return nil end
        local n=a*262144+b*4096+(c or 0)*64+(d or 0)
        counter=counter+1
        if c==nil then
            out[counter]=string.char(math.floor(n/65536)%256)
        elseif d==nil then
            out[counter]=string.char(math.floor(n/65536)%256,math.floor(n/256)%256)
        else
            out[counter]=string.char(math.floor(n/65536)%256,math.floor(n/256)%256,n%256)
        end
    end
    local data=table.concat(out)
    posterCache[eventId]=data
    return data
end

