    Gravity="Mythical", Mammoth="Mythical", ["T-Rex"]="Mythical",
    Dough="Mythical", Shadow="Mythical", Venom="Mythical",
    Gas="Mythical", Spirit="Mythical", Tiger="Mythical", Yeti="Mythical",
    Magnet="Mythical", Kitsune="Mythical", Control="Mythical", Dragon="Mythical",
}
local FRUIT_COLORS = {
    Common=9807270, Uncommon=3066993, Rare=3447003,
    Legendary=15844367, Mythical=15105570,
}
local FRUIT_HIGH_RES = {
    Gas="https://wikiassets.net/bloxfruits-3bec24/images/20b26681dda188c523cd23a73425e1d8.webp",
    Kitsune="https://wikiassets.net/bloxfruits-3bec24/images/be07ec067c6f44dd1141b806b0fbf7cd.webp",
    Dragon="https://wikiassets.net/bloxfruits-3bec24/images/c17c3878fc62726beca8774a107e2e09.webp",
    Magnet="https://wikiassets.net/bloxfruits-3bec24/images/896b3a0f6578535ac56efed826bbe1b1.webp",
}
local FRUIT_ALIASES = {
    hellfire={base="Gas", title="Hellfire (Gas)"},
    werewolf={base="Tiger", title="Werewolf (Tiger)"},
    empyrean={base="Kitsune", title="Empyrean (Kitsune)"},
    fiend={base="Yeti", title="Fiend (Yeti)"},
    leopard={base="Tiger", title="Tiger (Leopard cũ)"},
    falcon={base="Eagle", title="Eagle (Falcon cũ)"},
    rumble={base="Lightning", title="Lightning (Rumble cũ)"},
    barrier={base="Creation", title="Creation (Barrier cũ)"},
    paw={base="Pain", title="Pain (Paw cũ)"},
}

-- Receives names such as "Gas Fruit", "Gas-Gas Fruit", "Hellfire (Gas)".
local function fruitInfo(rawName)
    local raw=tostring(rawName or "")
    local compact=normalize(raw)
    if compact=="" or #compact>100 then return nil end
    for tag,alias in pairs(FRUIT_ALIASES) do
        if compact:find(tag,1,true) then
            return alias.base,alias.title,FRUIT_RARITIES[alias.base]
        end
    end
    for name,rarity in pairs(FRUIT_RARITIES) do
        local key=normalize(name)
        if compact==key or compact==key..key or compact==key.."fruit" or compact==key..key.."fruit"
            or compact=="blox"..key.."fruit" then
            -- For legacy names use current official name.
            if name=="Falcon" then name="Eagle" end
            if name=="Rumble" then name="Lightning" end
            return name,name,rarity
        end
    end
    -- Legacy item IDs from getInventoryFruits, e.g. "Human-Human: Buddha".
    if compact:find("humanhumanbuddha",1,true) then
        return "Buddha","Buddha",FRUIT_RARITIES.Buddha
    end
    if compact:find("birdbirdphoenix",1,true) then
        return "Phoenix","Phoenix",FRUIT_RARITIES.Phoenix
    end
    if compact:find("birdbirdfalcon",1,true) then
        return "Eagle","Eagle",FRUIT_RARITIES.Eagle
    end
    return nil
end

local FRUIT_MUTATION_IMAGES = {
    hellfire="https://bffr.fr/wiki/assets/img/mutations/g-hellfire.webp",
    werewolf="https://bffr.fr/wiki/assets/img/mutations/g-werewolf.webp",
    empyrean="https://bffr.fr/wiki/assets/img/mutations/g-empyrean.webp",
    fiend="https://bffr.fr/wiki/assets/img/mutations/g-fiend.webp",
}
local function fruitImage(base,displayName)
    local key=normalize(displayName or "")
    for mutation,url in pairs(FRUIT_MUTATION_IMAGES) do
        if key:find(mutation,1,true) then return url end
    end
    if FRUIT_HIGH_RES[base] then return FRUIT_HIGH_RES[base] end
    local fileName=base:gsub(" ","_")
    return "https://raw.githubusercontent.com/blackxscripts/blox-fruits/main/"
        ..fileName.."_Fruit.png"
end

local function seaName()
    local id=tonumber(game.PlaceId)
    if id==2753915549 then return "First Sea (1)" end
    if id==4442272183 then return "Second Sea (2)" end
    if id==7449423635 then return "Third Sea (3)" end
    return "Không rõ"
end

local function nearGacha()
    local char=LocalPlayer.Character
    local root=char and char:FindFirstChild("HumanoidRootPart")
    local folder=workspace:FindFirstChild("NPCs")
    if not root or not folder then return false end
    for _,npc in ipairs(folder:GetChildren()) do
        local name=normalize(npc.Name)
        if name:find("zioles",1,true) or name:find("gacha",1,true)
            or name:find("cousin",1,true) then
            local part=npc:IsA("BasePart") and npc
                or (npc:IsA("Model") and (npc.PrimaryPart or npc:FindFirstChild("HumanoidRootPart")
                    or npc:FindFirstChildWhichIsA("BasePart")))
            if part and (part.Position-root.Position).Magnitude<=27 then return true end
        end
    end
    return false
end

-- V4.6 neon poster sent as a Discord file; title contains REAL player name.
-- A webhook embed itself cannot have a gradient background. The poster is an image.
local function sendFruitDiscord(fruitName,isTest,isGacha,isManual,isStored)
    if not validWebhook(S.webhook) then
        status("Hay luu Discord webhook truoc khi bao trai",false)
        return false
    end
    local req=discordRequest()
    if not req then status("Executor khong ho tro HTTP request",false); return false end
    local baseName,displayName,rarity=fruitInfo(fruitName)
    if not baseName then status("Khong nhan ra trai: "..tostring(fruitName),false); return false end

    local playerName=tostring(LocalPlayer.Name or "Unknown")
    local displayPlayer=tostring(LocalPlayer.DisplayName or playerName)
    local fruitUrl=fruitImage(baseName,displayName)
    local isHellfire=normalize(displayName):find("hellfire",1,true)~=nil
    -- Chi Hellfire co poster rieng voi anh trai duoc ghep san.
    -- Voi moi trai khac: dung hinh TRAI THAT o khu vuc anh lon,
    -- khong gui poster generic voi bieu tuong rong / loi font nua.
    local useEmbeddedPoster=isHellfire
    local posterKey=isHellfire and (isStored or isTest) and "stored_hellfire" or "hellfire"
    local filename="truongcoder_v47_"..posterKey..".jpg"
    local eventLabel
    if isTest then eventLabel="🧪 TIN THỬ MẪU ĐÃ CẤT — KHÔNG CẤT THẬT"
    elseif isStored then eventLabel="✅ ĐÃ CẤT TRÁI ÁC QUỶ"
    elseif isManual then eventLabel="🍎 TRÁI ĐANG CẦM"
    elseif isGacha then eventLabel="🎰 NHẬN TRÁI GẦN NPC GACHA"
    else eventLabel="🍎 PHÁT HIỆN TRÁI MỚI" end
    local note=isTest and "Ảnh mẫu để xem giao diện; chưa có lượt cất trái nào được xác nhận."
      or isStored and "Số lượng trái này trong kho đã tăng so với lần kiểm tra trước."
      or isManual and "Báo trái mà nhân vật đang cầm."
      or isGacha and "Vật phẩm trái mới xuất hiện khi đứng gần NPC Gacha; chưa xác minh nguồn nhận."
      or "Phát hiện một Tool trái mới xuất hiện trong Backpack / nhân vật."
    local id=tostring(game.JobId)
    if id=="" then id="Không có" end
    -- Dynamic player name and actual fruit appear as heading in Discord.
    local embed={
        author={name="TRUONG CODER HD • FRUIT WATCH V4.7"},
        title=isTest and ("🧪 MẪU ĐÃ CẤT TRÁI ÁC QUỶ • "..displayName)
            or isStored and ("✅ ĐÃ CẤT TRÁI ÁC QUỶ • "..displayName)
            or ("👑 "..displayPlayer.."  |  🍎 "..displayName),
        description="## 👑 "..displayPlayer.."\n"
            .."**👤 @"..playerName.."**\n"
            .."**"..eventLabel.."**\n"
            .."**💎 "..tostring(rarity or "Chưa rõ").."**  •  **🍇 "..displayName.."**\n"
            .."*"..note.."*",
        color=(isStored and not isTest) and 0x59EAC5 or 0xB985FF,
        thumbnail={url=fruitUrl},
        -- Neu la Lightning, Dragon, Kitsune... thi anh lon chinh la anh trai,
        -- KHONG phai nen mau khong co trai.
        image={url=useEmbeddedPoster and ("attachment://"..filename) or fruitUrl},
        fields={
            {name="👑 TÊN NHÂN VẬT",value="**"..displayPlayer.."** (`"..playerName.."`)",inline=false},
            {name="🌊 SEA",value=seaName(),inline=true},
            {name="🎮 PLACE ID",value="`"..tostring(game.PlaceId).."`",inline=true},
            {name="🖥️ SERVER JOB ID",value="`"..id.."`",inline=false}
        },
        footer={text=isTest and "TRUONG CODER V4.7 • TEST"
            or isStored and "TRUONG CODER V4.7 • STORED FRUIT VERIFIED BY INVENTORY CHANGE"
            or "TRUONG CODER V4.7 • FRUIT ALERT"},
        timestamp=os.date("!%Y-%m-%dT%H:%M:%SZ")
    }
    local mention=S.fruitMentionEveryone and not isTest
    local payload={
        username="TRUONG CODER | FRUIT WATCH",
        content=mention and "@everyone" or nil,
        allowed_mentions={parse=mention and {"everyone"} or {}},
        embeds={embed}
    }
    local url=S.webhook
    status("Dang gui thong bao co anh trai: "..displayName.."...",true)
    task.spawn(function()
        local ok,res=pcall(function()
            if useEmbeddedPoster then
                -- Poster Hellfire co anh trai ghep san tren nen neon.
                local jpg=decodePoster(posterKey)
                if not jpg then error("Khong doc duoc poster Hellfire") end
                local boundary="----TruongCoderFruitNeon"..tostring(math.floor(os.clock()*100000))
                local json=HttpService:JSONEncode(payload)
                local body=table.concat({
                    "--",boundary,"\r\n",
                    'Content-Disposition: form-data; name="payload_json"',"\r\n",
                    "Content-Type: application/json\r\n\r\n",json,"\r\n",
                    "--",boundary,"\r\n",
                    'Content-Disposition: form-data; name="files[0]"; filename="',filename,'"',"\r\n",
                    "Content-Type: image/jpeg\r\n\r\n",jpg,"\r\n",
                    "--",boundary,"--\r\n"
                })
                return req({
                    Url=url,Method="POST",
                    Headers={["Content-Type"]="multipart/form-data; boundary="..boundary},
                    Body=body
                })
            end
            -- Cac trai khac su dung anh trai URL truc tiep lam ANH LON.
            -- Cac bo anh dinh kem co san khong duoc nhan dien dong, nen
            -- khong co the ghep nen neon vao anh moi ngay tren thiet bi.
            return req({
                Url=url,Method="POST",
                Headers={["Content-Type"]="application/json"},
                Body=HttpService:JSONEncode(payload)
            })
        end)
        if not running then return end
        local code=ok and tonumber(res and (res.StatusCode or res.Status))
        if code and code>=200 and code<300 then
            status("DA GUI ANH TRAI: "..displayName,true)
        else
            local why=tostring(code or (ok and (res and res.Body or "Unknown") or res))
            status("GUI ANH THAT BAI: "..why:sub(1,100),false)
            warn("[TRUONG CODER FRUIT V4.7]",why)
        end
    end)
    return true
end

-- Mark tools already in inventory as 'seen', to avoid falsely reporting them
-- as fresh Gacha results on each executor restart.
local observedFruitTools=setmetatable({}, {__mode="k"})
local lastFruitNotice={}
local fruitMonitorStats = {toolNotices=0,storedNotices=0,inventoryChecks=0,inventoryErrors=0,lastError="",lastInventory=0}
local function observeFruitTool(item,existing)
    if not running or not item or not item:IsA("Tool") or observedFruitTools[item] then return end
    local base,displayName=fruitInfo(item.Name)
    if not base then return end
    observedFruitTools[item]=true
    if existing or not S.autoFoundFruitDiscord then return end
    local now=os.clock()
    if lastFruitNotice[displayName] and now-lastFruitNotice[displayName]<4 then return end
    lastFruitNotice[displayName]=now
    fruitMonitorStats.toolNotices=fruitMonitorStats.toolNotices+1
    status("PHAT HIEN TRAI MOI TRONG BALO: "..displayName,true)
    sendFruitDiscord(displayName,false,nearGacha(),false)
end

local function watchFruitContainer(container)
    if not container then return end
    for _,child in ipairs(container:GetChildren()) do
        observeFruitTool(child,true)
    end
    on(container.ChildAdded:Connect(function(child)
        if not running or not child:IsA("Tool") then return end
        -- Allow the Tool's actual name to settle after replication.
        task.delay(0.15,function()
            if running and child.Parent then observeFruitTool(child,false) end
        end)
    end))
end

local function startFruitWatch()
    local backpack=LocalPlayer:FindFirstChildOfClass("Backpack")
        or LocalPlayer:WaitForChild("Backpack",10)
    if backpack then watchFruitContainer(backpack) end
    local character=LocalPlayer.Character
    if character then watchFruitContainer(character) end
    on(LocalPlayer.CharacterAdded:Connect(function(newCharacter)
        watchFruitContainer(newCharacter)
    end))
    -- V4.8: scan occasionally as a fallback for delayed tool replication.
    -- Previously seen Tool objects are ignored, so re-equipping won't re-alert.
    while running do
        for _,container in ipairs({LocalPlayer:FindFirstChildOfClass("Backpack"),LocalPlayer.Character}) do
            if container then
                for _,item in ipairs(container:GetChildren()) do
                    observeFruitTool(item,false)
                end
            end
        end
        task.wait(3)
    end
end

-- V4.6: check server inventory changes instead of guessing from Backpack alone.
-- A snapshot is taken at startup so older stored fruits do not generate fake alerts.
-- "getInventoryFruits" comes from Blox Fruits's existing inventory interface;
-- it is only used for reading, not for storing/buying fruits.
local function readStoredFruits()
    local remotes=game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
    local remote=remotes and remotes:FindFirstChild("CommF_")
    if not remote or not remote:IsA("RemoteFunction") then return nil end
    local ok,items=pcall(function()
        return remote:InvokeServer("getInventoryFruits")
    end)
    fruitMonitorStats.inventoryChecks=fruitMonitorStats.inventoryChecks+1
    if not ok or type(items)~="table" then
        fruitMonitorStats.inventoryErrors=fruitMonitorStats.inventoryErrors+1
        fruitMonitorStats.lastError = ok and ("Inventory response: "..typeof(items)) or tostring(items)
        return nil
    end
    local result={}
    for _,item in pairs(items) do
        if type(item)=="table" and type(item.Name)=="string" then
            local key=normalize(item.Name)
            if key~="" then
                local qty=tonumber(item.Count or item.Quantity or item.Amount) or 1
                qty=math.max(0,math.floor(qty))
                if result[key] then
                    result[key].count=result[key].count+qty
                else
                    result[key]={name=item.Name,count=qty}
                end
            end
        end
    end
    local total=0
    for _,fruit in pairs(result) do total=total+fruit.count end
    fruitMonitorStats.lastInventory=total
    return result
end

local function fruitDiagnostics()
    local requestReady=discordRequest() ~= nil
    local hookReady=validWebhook(S.webhook)
    local stored=readStoredFruits()
    local count=0
    if stored then for _ in pairs(stored) do count=count+1 end end
    local msg="HTTP: "..(requestReady and "OK" or "KHONG HO TRO")
        .." | WEBHOOK: "..(hookReady and "OK" or "CHUA LUU")
        .." | KHO: "..(stored and (tostring(count).." LOAI") or "KHONG DOC DUOC")
    status(msg,requestReady and hookReady and stored~=nil)
    warn("[TRUONG CODER V4.8 DIAGNOSTICS] "..msg
        .." | fruit-tool notices="..tostring(fruitMonitorStats.toolNotices)
        .." | stored notices="..tostring(fruitMonitorStats.storedNotices)
        .." | inventory errors="..tostring(fruitMonitorStats.inventoryErrors)
        .." | last error="..tostring(fruitMonitorStats.lastError))
end

local function startStoredFruitWatch()
    local previous=nil
    local failed=0
    while running do
        if not S.autoFruitDiscord then
            previous=nil
        else
            local current=readStoredFruits()
            if current then
                failed=0
                if previous then
                    for key,item in pairs(current) do
                        local old=previous[key]
                        if item.count>(old and old.count or 0) then
                            local base=fruitInfo(item.name)
                            if base then
                                fruitMonitorStats.storedNotices=fruitMonitorStats.storedNotices+1
                                status("KHO VUA TANG: "..item.name.." (+"..tostring(item.count-(old and old.count or 0))..")",true)
                                sendFruitDiscord(item.name,false,false,false,true)
                            else
                                warn("[TRUONG CODER V4.8] Unknown inventory fruit name: "..tostring(item.name))
                            end
                        end
                    end
                end
                previous=current
            else
                failed=failed+1
                -- Do not replace the previous snapshot on a temporary server failure.
                if failed==1 then
                    warn("[TRUONG CODER V4.8] Cannot read stored-fruit inventory: "..tostring(fruitMonitorStats.lastError))
                end
            end
        end
        task.wait(4)
    end
end

local function reportHeldFruit()
    local character=LocalPlayer.Character
    local backpack=LocalPlayer:FindFirstChildOfClass("Backpack")
    for _,parent in ipairs({character,backpack}) do
        if parent then
            for _,tool in ipairs(parent:GetChildren()) do
                if tool:IsA("Tool") and fruitInfo(tool.Name) then
                    sendFruitDiscord(tool.Name,false,false,true)
                    return
                end
            end
        end
    end
    status("Khong tim thay trai vat ly trong tay / balo",false)
end

-- Pretty island Webhook with embedded AURICZ600 posters (image/jpeg attachment).
-- The sender only reports detected objects; it does NOT spawn any island.
-- TEST always says "preview", even when the sample poster has success text.
local function sendDiscord(eventId,pos,isTest)
    if not validWebhook(S.webhook) then
        status("Chua luu Webhook hop le",false)
        return
    end
    local req=discordRequest()
    if not req then
        status("Delta khong ho tro HTTP request",false)
        return
    end
    local info=EVENTS[eventId]
    if not info then
        status("Khong nhan ra ten dao: "..tostring(eventId),false)
        return
    end

    local dist=distance(pos)
    local distText=isTest and "TEST" or (dist and (tostring(dist).." studs") or "Chưa rõ")
    local xyz=isTest and "Chưa có - tin thử" or positionString(pos)
    local jobid=tostring(game.JobId)
    if jobid=="" then jobid="Không có" end
    local filename="trungcoder_"..eventId..".jpg"
    local embed={
        author={name="TRUONG CODER • SEA WATCH | AURICZ600"},
        title=isTest and ("🧪 XEM TRƯỚC | "..info.name)
            or ("🚨 "..info.name.." XUẤT HIỆN!"),
        description=isTest
            and ("🧪 **TIN THỬ POSTER** — chưa có đảo thật được xác nhận.\n👑 Thiết kế: **AURICZ600**")
            or ("✅ **RADAR ĐÃ PHÁT HIỆN DẤU MỐC ĐẢO TRONG SERVER!**\n👑 Poster: **AURICZ600**"),
        color=info.color,
        fields={
            {name="🏝️ ĐẢO",value="**"..info.vn.."**",inline=true},
            {name="🌊 KHU VỰC",value="**THIRD SEA**",inline=true},
            {name="📏 KHOẢNG CÁCH",value="**"..distText.."**",inline=true},
            {name="📍 TỌA ĐỘ",value="`"..xyz.."`",inline=false},
            {name="🧭 SERVER ID",value="`"..jobid.."`",inline=false},
            {name="🎮 PLACE ID",value="`"..tostring(game.PlaceId).."`",inline=true}
        },
        image={url="attachment://"..filename},
        footer={text=isTest
            and "TRUONG CODER SEA WATCH • POSTER DEMO • AURICZ600"
            or "TRUONG CODER SEA WATCH • ẢNH POSTER • AURICZ600"},
        timestamp=os.date("!%Y-%m-%dT%H:%M:%SZ")
    }
    local payload={
        username="TRUONG CODER | SEA WATCH",
        allowed_mentions={parse={}},
        embeds={embed}
    }
    local url=S.webhook
    status("Dang gui poster "..info.name.."...",true)
    task.spawn(function()
        local ok,res=pcall(function()
            local img=decodePoster(eventId)
            if not img then error("Khong doc duoc anh poster") end
            local boundary="----TruongCoderAURICZ600"..tostring(math.floor(os.clock()*100000))
            local json=HttpService:JSONEncode(payload)
            local body=table.concat({
                "--",boundary,"\r\n",
                'Content-Disposition: form-data; name="payload_json"',"\r\n",
                "Content-Type: application/json\r\n\r\n",json,"\r\n",
                "--",boundary,"\r\n",
                'Content-Disposition: form-data; name="files[0]"; filename="',filename,'"',"\r\n",
                "Content-Type: image/jpeg\r\n\r\n",img,"\r\n",
                "--",boundary,"--\r\n"
            })
            return req({
                Url=url,Method="POST",
                Headers={
                    ["Content-Type"]="multipart/form-data; boundary="..boundary
                },
                Body=body
            })
        end)
        if not running then return end
        local code=ok and tonumber(res and (res.StatusCode or res.Status))
        if code and code>=200 and code<300 then
            status(isTest and ("DA GUI TEST CO POSTER: "..info.name)
                or ("DA BAO DAO KEM POSTER: "..info.name),true)
        else
            local errText=tostring(code or (ok and (res and res.Body or "Unknown") or res))
            status("GUI ANH DISCORD THAT BAI: "..errText:sub(1,110),false)
            warn("[TC Webhook multipart]",errText)
        end
    end)
end

