-- ========================================================
-- SPEED / JUMP: per-character restore, configurable in GUI
-- ========================================================
local motionBackup = setmetatable({}, {__mode = "k"})
local function humanoidNow()
    local character = LocalPlayer.Character
    return character and character:FindFirstChildOfClass("Humanoid") or nil
end
local function restoreMotion(hum)
    local old = motionBackup[hum]
    if not old or not hum or not hum.Parent then return end
    pcall(function()
        if old.speedApplied then hum.WalkSpeed = old.walkSpeed end
        if old.jumpApplied then
            hum.UseJumpPower = old.useJumpPower
            hum.JumpPower = old.jumpPower
            hum.JumpHeight = old.jumpHeight
        end
    end)
    old.speedApplied = false
    old.jumpApplied = false
end
local function applyMotion()
    if not running then return end
    local hum = humanoidNow()
    if not hum then return end
    local old = motionBackup[hum]
    if not old and (S.speedEnabled or S.jumpEnabled) then
        old = {speedApplied = false, jumpApplied = false}
        motionBackup[hum] = old
    end
    if not old then return end
    pcall(function()
        if S.speedEnabled then
            if not old.speedApplied then
                old.walkSpeed = hum.WalkSpeed
                old.speedApplied = true
            end
            if hum.WalkSpeed ~= S.walkSpeed then hum.WalkSpeed = S.walkSpeed end
        elseif old.speedApplied then
            hum.WalkSpeed = old.walkSpeed
            old.speedApplied = false
        end
        if S.jumpEnabled then
            if not old.jumpApplied then
                old.useJumpPower = hum.UseJumpPower
                old.jumpPower = hum.JumpPower
                old.jumpHeight = hum.JumpHeight
                old.jumpApplied = true
            end
            if not hum.UseJumpPower then hum.UseJumpPower = true end
            if hum.JumpPower ~= S.jumpPower then hum.JumpPower = S.jumpPower end
        elseif old.jumpApplied then
            hum.UseJumpPower = old.useJumpPower
            hum.JumpPower = old.jumpPower
            hum.JumpHeight = old.jumpHeight
            old.jumpApplied = false
        end
    end)
end
local function slider(page, caption, key, minValue, maxValue, step, tint)
    local frame = corners(create("Frame", page, {
        Size = UDim2.new(1, 0, 0, 100),
        BackgroundColor3 = T.surface2,
        BorderSizePixel = 0
    }), 10)
    local text = label(frame, caption, 12, T.text)
    text.Position = UDim2.fromOffset(12, 8)
    text.Size = UDim2.new(1, -104, 0, 28)
    local valueBox = corners(create("TextBox", frame, {
        BackgroundColor3 = T.surface3,
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(78, 30),
        Position = UDim2.new(1, -89, 0, 8),
        TextColor3 = T.mint,
        TextSize = 15,
        Font = Enum.Font.GothamBold,
        ClearTextOnFocus = false,
        Text = tostring(S[key])
    }), 7)
    local track = corners(create("Frame", frame, {
        Position = UDim2.new(0, 14, 0, 65),
        Size = UDim2.new(1, -28, 0, 10),
        BackgroundColor3 = T.surface3,
        BorderSizePixel = 0,
        Active = true
    }), 5)
    local fill = corners(create("Frame", track, {
        Size = UDim2.fromScale(0, 1),
        BackgroundColor3 = tint or T.cyan,
        BorderSizePixel = 0
    }), 5)
    local knob = corners(create("TextButton", track, {
        Text = "",
        AutoButtonColor = false,
        Size = UDim2.fromOffset(22, 22),
        AnchorPoint = Vector2.new(.5, .5),
        Position = UDim2.fromScale(0, .5),
        BackgroundColor3 = T.text,
        BorderSizePixel = 0
    }), 11)
    border(knob, tint or T.cyan, 2, 0.1)
    local function updateVisual()
        local a = (S[key] - minValue) / (maxValue - minValue)
        fill.Size = UDim2.fromScale(a, 1)
        knob.Position = UDim2.fromScale(a, .5)
        if not valueBox:IsFocused() then valueBox.Text = tostring(S[key]) end
    end
    local function setNumber(v, saveIt)
        if type(v) ~= "number" or v ~= v then return end
        S[key] = math.clamp(math.floor(v / step + 0.5) * step, minValue, maxValue)
        updateVisual()
        applyMotion()
        if saveIt then saveConfig(false) end
    end
    local dragType = nil
    local dragInput = nil
    local function fromX(x, saveIt)
        local w = math.max(track.AbsoluteSize.X, 1)
        local t = math.clamp((x - track.AbsolutePosition.X) / w, 0, 1)
        setNumber(minValue + (maxValue - minValue) * t, saveIt)
    end
    local function start(inputObject)
        local kind = inputObject.UserInputType
        if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
        dragType = kind
        dragInput = inputObject
        fromX(inputObject.Position.X, false)
    end
    on(track.InputBegan:Connect(start))
    on(knob.InputBegan:Connect(start))
    on(UserInputService.InputChanged:Connect(function(inputObject)
        if not dragType then return end
        if dragType == Enum.UserInputType.MouseButton1
            and inputObject.UserInputType == Enum.UserInputType.MouseMovement then
            fromX(inputObject.Position.X, false)
        elseif dragType == Enum.UserInputType.Touch and inputObject == dragInput then
            fromX(inputObject.Position.X, false)
        end
    end))
    on(UserInputService.InputEnded:Connect(function(inputObject)
        if dragType == Enum.UserInputType.MouseButton1
            and inputObject.UserInputType == Enum.UserInputType.MouseButton1 then
            dragType = nil
            dragInput = nil
            saveConfig(false)
        elseif dragType == Enum.UserInputType.Touch and inputObject == dragInput then
            dragType = nil
            dragInput = nil
            saveConfig(false)
        end
    end))
    on(valueBox.FocusLost:Connect(function()
        local raw = tonumber(valueBox.Text)
        if raw then setNumber(raw, true) else updateVisual() end
    end))
    updateVisual()
    return updateVisual
end

local function toggle(page,message,key)
    local row=corners(create("Frame",page,{
        Size=UDim2.new(1,0,0,48),
        BackgroundColor3=T.surface2,
        BorderSizePixel=0
    }),9)
    local caption=label(row,message,12,T.text)
    caption.Position=UDim2.fromOffset(9,3)
    caption.Size=UDim2.new(1,-97,1,-6)
    local tap=button(row,S[key] and "BẬT" or "TẮT",S[key] and color(18,131,102) or color(105,52,68))
    tap.Size=UDim2.fromOffset(78,32)
    tap.Position=UDim2.new(1,-86,.5,-16)
    toggleSetters[key]=function()
        tap.Text=S[key] and "BẬT" or "TẮT"
        tap.BackgroundColor3=S[key] and color(18,131,102) or color(105,52,68)
    end
    on(tap.MouseButton1Click:Connect(function()
        S[key]=not S[key]
        -- Water walking needs body collision; Noclip and Water Walk cannot both stay active.
        if key == "waterWalk" and S.waterWalk and S.noclip then
            S.noclip = false
            if toggleSetters.noclip then toggleSetters.noclip() end
        elseif key == "noclip" and S.noclip and S.waterWalk then
            S.waterWalk = false
            if toggleSetters.waterWalk then toggleSetters.waterWalk() end
        end
        toggleSetters[key]()
        if key=="speedEnabled" or key=="jumpEnabled" then applyMotion() end
        saveConfig(false)
        if key=="noclip" and not S.noclip then
            -- Restored in stepped update on next frame.
            status("Da tat di xuyen tuong",true)
        end
    end))
    return row
end

