-- Drag window (header) and compact photo button independently.
local function drag(surface,target,savePosition)
    local dragging=false
    local startInput,startPos,currentTouch
    local changed=false
    local endConn
    on(surface.InputBegan:Connect(function(inputEvent)
        local typ=inputEvent.UserInputType
        if typ~=Enum.UserInputType.MouseButton1 and typ~=Enum.UserInputType.Touch then return end
        dragging=true
        changed=false
        startInput=inputEvent.Position
        startPos=target.Position
        currentTouch=typ==Enum.UserInputType.Touch and inputEvent or nil
        if endConn then endConn:Disconnect() end
        endConn=inputEvent.Changed:Connect(function()
            if inputEvent.UserInputState==Enum.UserInputState.End then
                dragging=false
                if changed then savePosition() end
                if endConn then endConn:Disconnect(); endConn=nil end
            end
        end)
    end))
    on(UserInputService.InputChanged:Connect(function(inputEvent)
        if not dragging then return end
        if currentTouch then
            if inputEvent~=currentTouch then return end
        elseif inputEvent.UserInputType~=Enum.UserInputType.MouseMovement then
            return
        end
        local delta=inputEvent.Position-startInput
        if delta.Magnitude>5 then changed=true end
        if not changed then return end
        target.Position=UDim2.new(
            startPos.X.Scale,startPos.X.Offset+delta.X,
            startPos.Y.Scale,startPos.Y.Offset+delta.Y
        )
    end))
    return function() return changed end
end

drag(header,hub,function()
