    S.hubY=math.clamp(hub.Position.Y.Scale+hub.Position.Y.Offset/math.max(1,workspace.CurrentCamera.ViewportSize.Y),0.08,0.92)
    hub.Position=UDim2.fromScale(S.hubX,S.hubY)
    saveConfig(false)
end)

