-- ESP markers. Local-only BillboardGui labels.
-- ==========================================
local markerFolder=create("Folder",workspace.CurrentCamera or workspace,{Name="TC_ESP_LOCAL_MARKER_ANCHORS"})
local CATS={
    island={color=T.cyan,cap=4},
    npc={color=T.rose,cap=110},
    player={color=T.violet,cap=80},
    fruit={color=T.yellow,cap=70}
}
local counts={island=0,npc=0,player=0,fruit=0}

local function clearMarker(item)
    if not item then return end
    pcall(function() item.gui:Destroy() end)
    if item.anchor then pcall(function() item.anchor:Destroy() end) end
end

local function mark(obj,category,display,desired)
    if not obj or not obj.Parent then return end
    if desired[obj] then return end
    if counts[category]>=CATS[category].cap then return end
    local pos=objectPosition(obj)
    if not pos then return end
    local objPart=objectPart(obj)
    desired[obj]={category=category,title=display}
    counts[category]=counts[category]+1
    local existing=markers[obj]
    if existing and existing.category~=category then
        clearMarker(existing)
        markers[obj]=nil
        existing=nil
    end
    if not existing then
        local anchor
        if not objPart then
            -- CFrameValue and Vector3Value locations are invisible; make local anchor.
            anchor=create("Part",markerFolder,{
                Name="LOCAL_ESP_ANCHOR",Size=Vector3.new(.25,.25,.25),
                Anchored=true,CanCollide=false,CanTouch=false,CanQuery=false,
                Transparency=1,CFrame=CFrame.new(pos)
            })
            objPart=anchor
        end
        local billboard=create("BillboardGui",PlayerGui,{
            Name="TC_MARKER_"..category,
            Adornee=objPart,
            Size=UDim2.fromOffset(150,26),
            StudsOffsetWorldSpace=Vector3.new(0,5,0),
            AlwaysOnTop=true,
            MaxDistance=100000
        })
        local bg=corners(create("Frame",billboard,{
            Size=UDim2.fromScale(1,1),
            BackgroundColor3=T.background,
            BackgroundTransparency=0.40,
            BorderSizePixel=0
        }),8)
        local eventId=(category=="island") and ALIASES[normalize(obj.Name)] or nil
        local markerColor=EVENT_COLORS[eventId] or CATS[category].color
        border(bg,markerColor,1,0.2)
        local lbl=label(bg,"",10,markerColor)
        lbl.TextXAlignment=Enum.TextXAlignment.Center
        lbl.TextStrokeTransparency=0.85
        lbl.Size=UDim2.fromScale(1,1)
        markers[obj]={gui=billboard,anchor=anchor,label=lbl,category=category}
        existing=markers[obj]
    end
    if existing.anchor and existing.anchor.Parent then
        existing.anchor.Position=pos
    end
    if existing.gui and objPart then
        existing.gui.Adornee=objPart
    end
    local d=distance(pos)
    local compactDistance="?"
    if d then
        compactDistance=(d>=1000) and string.format("%.1fk",d/1000) or tostring(d)
    end
    existing.label.Text=display.."  •  "..compactDistance
end

local function isFruit(obj)
    if not obj or not (obj:IsA("Tool") or obj:IsA("Model")) then return false end
    local n=obj.Name:lower()
    if not n:find("fruit",1,true) then return false end
    for _,exclude in ipairs({"dealer","gacha","spawner","stock","tree","raid","npc"}) do
        if n:find(exclude,1,true) then return false end
    end
    local character=LocalPlayer.Character
    if character and obj:IsDescendantOf(character) then return false end
    return objectPart(obj)~=nil
end

local function npcCandidate(obj,playerCharacters,fromNPCFolder)
    if not obj:IsA("Model") or playerCharacters[obj] then return false end
    -- Check cheap conditions before searching model parts (performance).
    local humanoid=obj:FindFirstChildOfClass("Humanoid")
    if not humanoid and not (fromNPCFolder and
        (obj:FindFirstChild("HumanoidRootPart") or obj:FindFirstChild("Head"))) then
        return false
    end
    return objectPart(obj)~=nil
end

local function collectIslands(markFn,eventsFound)
    local origin=workspace:FindFirstChild("_WorldOrigin")
    local loc=origin and origin:FindFirstChild("Locations")
    local map=workspace:FindFirstChild("Map")
    local seenLocal={}
    local function take(obj)
        if not obj or not obj.Parent or seenLocal[obj] then return end
        seenLocal[obj]=true
        -- Do NOT mark ordinary islands, temples, raid maps, or sea objects.
        local id=ALIASES[normalize(obj.Name)]
        if not id or eventsFound[id] then return end
        local pos=objectPosition(obj)
        if pos then eventsFound[id]={obj=obj,pos=pos} end
    end
    if loc then
        for _,obj in ipairs(loc:GetChildren()) do take(obj) end
    end
    if map then
        for _,obj in ipairs(map:GetChildren()) do take(obj) end
        for _,obj in ipairs(map:GetDescendants()) do
            if ALIASES[normalize(obj.Name)] then take(obj) end
        end
    end
    for _,obj in ipairs(workspace:GetChildren()) do
        if ALIASES[normalize(obj.Name)] then take(obj) end
    end
    -- Exactly one tiny ESP label for each of the four supported events.
    if S.espIslands then
        for id,entry in pairs(eventsFound) do
            markFn(entry.obj,"island",EVENT_TAGS[id])
        end
    end
end

-- Preserved from V1 for future optional extensions. In events-only mode not called.
local function collectNPCs(markFn,playerCharacters,items,worldDescendants)
    local visited={}
    local function take(model,fromNPCFolder)
        if #items>=140 then return end
        if not model:IsA("Model") or visited[model] or playerCharacters[model] then return end
        visited[model]=true
        if npcCandidate(model,playerCharacters,fromNPCFolder) then
            items[#items+1]=model
            markFn(model,"npc","NPC: "..model.Name)
        end
    end
    for _,rootName in ipairs({"Enemies","NPCs","Characters","WorldNPCs"}) do
        local folder=workspace:FindFirstChild(rootName)
        if folder then
            for _,obj in ipairs(folder:GetDescendants()) do take(obj,true) end
        end
    end
    -- Fallback: quest NPC and combat NPC outside usual folders.
    -- Scan only models with a Humanoid and cap displays.
    if #items<110 then
        for _,obj in ipairs(worldDescendants) do
            take(obj,false)
            if #items>=140 then break end
        end
    end
end

local function scanWorld()
    if not running or scanning then return end
    scanning=true
    local wanted={}
    for key in pairs(counts) do counts[key]=0 end
    local eventsFound={}
    -- Reuse one workspace snapshot for NPC and fruit scans.
    local worldDescendants={}
    -- NPC / Fruit / Player ESP disabled by request; never scan all descendants.
    if false then
        worldDescendants=workspace:GetDescendants()
    end
    local playerCharacters={}
    for _,other in ipairs(Players:GetPlayers()) do
        if other.Character then playerCharacters[other.Character]=true end
    end
    local function want(obj,category,title)
        mark(obj,category,title,wanted)
    end
    collectIslands(want,eventsFound)
    if false then
        for _,other in ipairs(Players:GetPlayers()) do
            if other~=LocalPlayer and other.Character then
                want(other.Character,"player","PLAYER: "..other.DisplayName)
            end
        end
    end
    if false then
        local items={}
        collectNPCs(want,playerCharacters,items,worldDescendants)
    end
    if false then
        local foundFruit=0
        for _,obj in ipairs(worldDescendants) do
            if isFruit(obj) then
                want(obj,"fruit","FRUIT: "..obj.Name)
                foundFruit=foundFruit+1
                if foundFruit>=90 then break end
            end
        end
    end
    for obj,item in pairs(markers) do
        if not wanted[obj] or not obj.Parent then
            clearMarker(item)
            markers[obj]=nil
        end
    end
    local activeCount=0
    for _,n in pairs(counts) do activeCount=activeCount+n end
    if espCounter then
        espCounter.Text=string.format("ESP DAO SU KIEN: %d / 4 | AN TOAN MAN HINH",counts.island)
    end
    activeEvents=eventsFound
    local evtCount=0
    for id,entry in pairs(eventsFound) do
        evtCount=evtCount+1
        if not alerted[id] then
            alerted[id]=true
            lastFoundEvent=EVENTS[id].name.." | "..positionString(entry.pos)
            if S.autoDiscord and S.webhook~="" then
                sendDiscord(id,entry.pos,false)
            end
            notice("SEA EVENT", "Detected: "..EVENTS[id].name)
        end
    end
    if lastEventLabel then lastEventLabel.Text="GAN NHAT: "..lastFoundEvent end
    if islandCounter then
        islandCounter.Text="DAO SU KIEN: "..evtCount.." / 4 | DANG HIEN: "..counts.island
    end
    scanning=false
end

on(refreshButton.MouseButton1Click:Connect(function()
    local ok,err=pcall(scanWorld)
    if not ok then scanning=false; status("Loi ESP: "..tostring(err),false)
    else status("Da quet ESP",true) end
end))
on(islandScanButton.MouseButton1Click:Connect(function()
    local ok,err=pcall(scanWorld)
    if not ok then scanning=false; status("Loi radar: "..tostring(err),false)
    else status("Da quet dao",true) end
end))
on(sendCurrentButton.MouseButton1Click:Connect(function()
    if not validWebhook(S.webhook) then
        status("Hay luu webhook truoc",false)
        return
    end
    local sent=0
    for id,entry in pairs(activeEvents) do
        sendDiscord(id,entry.pos,false)
        sent=sent+1
    end
    if sent==0 then
        status("Hien chua phat hien dao event nao",false)
    else
        status("Dang gui "..sent.." thong bao dao",true)
    end
end))

-- ==========================================
-- Noclip: restore original collision states.
-- ==========================================
local function restoreCollision()
    for part,value in pairs(collisionOriginal) do
        if part and part.Parent then pcall(function() part.CanCollide=value end) end
        collisionOriginal[part]=nil
    end
end
on(RunService.Stepped:Connect(function()
    if not running then return end
    local character=LocalPlayer.Character
    if previousCharacter~=character then
        restoreCollision()
        previousCharacter=character
    end
    if S.noclip and character then
        for _,part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") then
                if collisionOriginal[part]==nil then
                    collisionOriginal[part]=part.CanCollide
                end
                part.CanCollide=false
            end
        end
    elseif next(collisionOriginal)~=nil then
        restoreCollision()
    end
end))

-- Speed V4.2: keep WalkSpeed in sync every frame, not every 0.25s.
-- Some games reassign WalkSpeed each render/physics frame. Physics assist is
-- best-effort only: server-side corrections can still limit actual movement.
on(RunService.RenderStepped:Connect(function()
    if S.speedEnabled or S.jumpEnabled then applyMotion() end
end))

local function assistRunningSpeed()
    if not running or not S.speedEnabled then return end
    local character = LocalPlayer.Character
    if not character then return end
    local hum = character:FindFirstChildOfClass("Humanoid")
    local root = character:FindFirstChild("HumanoidRootPart")
    if not hum or not root or root.Anchored or hum.Health <= 0 or hum.Sit then return end
    local state = hum:GetState()
    if state == Enum.HumanoidStateType.Seated
        or state == Enum.HumanoidStateType.Dead
        or state == Enum.HumanoidStateType.Swimming then return end
    local dir = hum.MoveDirection
    if dir.Magnitude < 0.05 then return end
    local speed = math.clamp(tonumber(S.walkSpeed) or 16, 16, 160)
    local unit = dir.Unit
    local velocity = root.AssemblyLinearVelocity
    local forwardSpeed = Vector3.new(velocity.X, 0, velocity.Z):Dot(unit)
    if forwardSpeed >= speed * 0.92 then return end
    -- Horizontal boost only. Preserve Y velocity so high jump stays independent.
    local horizontal = unit * speed
    root.AssemblyLinearVelocity = Vector3.new(horizontal.X, velocity.Y, horizontal.Z)
end
on(RunService.Heartbeat:Connect(function()
    if not running then return end
    if S.speedEnabled or S.jumpEnabled then applyMotion() end
    if S.speedEnabled then pcall(assistRunningSpeed) end
end))


-- ================================================================
-- V4.3: Water Walk - local invisible platform above actual water.
-- Raycast includes Terrain water and recognizes named ocean water parts.
-- This is client-side best effort. Some servers may override movement.
-- ================================================================
local waterPlatform = nil
local lastWaterUpdate = 0
local function removeWaterPlatform()
    if waterPlatform then
        pcall(function() waterPlatform:Destroy() end)
        waterPlatform = nil
    end
end
local function isWaterSurface(rayResult)
    if not rayResult then return false end
    if rayResult.Material == Enum.Material.Water then return true end
    local obj = rayResult.Instance
    if not obj or not obj:IsA("BasePart") then return false end
    local n = string.lower(obj.Name)
    return n:find("water", 1, true) ~= nil
        or n:find("ocean", 1, true) ~= nil
        or n == "sea"
end
local function updateWaterWalk(now)
    if not running or not S.waterWalk or S.noclip then
        removeWaterPlatform()
        return
    end
    if now - lastWaterUpdate < 0.11 then return end
    lastWaterUpdate = now
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not hum or not root or hum.Health <= 0 or hum.Sit or root.Anchored then
        removeWaterPlatform()
        return
    end
    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Exclude
    rayParams.IgnoreWater = false
    local excludes = {char}
    if waterPlatform then table.insert(excludes, waterPlatform) end
    rayParams.FilterDescendantsInstances = excludes
    local from = root.Position + Vector3.new(0, 14, 0)
    local result = workspace:Raycast(from, Vector3.new(0, -38, 0), rayParams)
    if not isWaterSurface(result) then
        if waterPlatform then waterPlatform.CanCollide = false end
        return
    end
    local surfaceY = result.Position.Y
    local distance = root.Position.Y - surfaceY
    if distance > 13 or distance < -12 then
        if waterPlatform then waterPlatform.CanCollide = false end
        return
    end
    if not waterPlatform then
        waterPlatform = Instance.new("Part")
        waterPlatform.Name = "TC_LOCAL_WATER_WALK_PLATFORM"
        waterPlatform.Anchored = true
        waterPlatform.CanCollide = true
        waterPlatform.CanTouch = false
        waterPlatform.Transparency = 1
        waterPlatform.Size = Vector3.new(12, 0.65, 12)
        waterPlatform.Parent = workspace
    end
    -- Part top face at water level. When already immersed, put platform just
    -- below the feet, so jumping can return the character to the surface.
    local topY = distance < 2.6 and (root.Position.Y - 2.95) or surfaceY + 0.04
    waterPlatform.Position = Vector3.new(root.Position.X, topY - 0.325, root.Position.Z)
    waterPlatform.CanCollide = true
end

-- ================================================================
-- V4.3: Auto Attack nearby NPCs, optionally equip combat tools.
-- No player targets, no hidden remote abuse, no auto quest/mob teleport.
-- ================================================================
local lastAttack = 0
local function equippedTool(char)
    return char and char:FindFirstChildOfClass("Tool") or nil
end
local function weaponKind(tool)
    if not tool or not tool:IsA("Tool") then return "" end
    local tip = string.lower(tostring(tool.ToolTip or ""))
    local name = string.lower(tool.Name)
    if tip:find("melee",1,true) or tip:find("combat",1,true) or name == "combat" then return "Melee" end
    if tip:find("sword",1,true) then return "Sword" end
    if tip:find("gun",1,true) then return "Gun" end
    return ""
end
local function preferredTool(char, hum)
    local current = equippedTool(char)
    local wanted = S.attackMode
    if current and (weaponKind(current) ~= "" and (wanted == "Auto" or weaponKind(current) == wanted)) then
        return current
    end
    local backpack = LocalPlayer:FindFirstChildOfClass("Backpack")
    if not backpack then return nil end
    local best, bestRank = nil, -1
    for _,tool in ipairs(backpack:GetChildren()) do
        if tool:IsA("Tool") then
            local kind = weaponKind(tool)
            if kind ~= "" and (wanted == "Auto" or kind == wanted) then
                local rank = (kind == "Melee" and 3) or (kind == "Sword" and 2) or 1
                if wanted ~= "Auto" then rank = 5 end
                if rank > bestRank then best, bestRank = tool, rank end
            end
        end
    end
    if best then
        pcall(function() hum:EquipTool(best) end)
        return equippedTool(char)
    end
    return nil
end
local function nearbyEnemy(root)
    local enemies = workspace:FindFirstChild("Enemies")
    if not enemies then return nil end
    local best, bestDist = nil, math.clamp(tonumber(S.attackRange) or 28, 8, 55)
    for _,model in ipairs(enemies:GetChildren()) do
        if model:IsA("Model") then
            local eHum = model:FindFirstChildOfClass("Humanoid")
            local eRoot = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
            if eHum and eRoot and eHum.Health > 0 then
                local d = (eRoot.Position-root.Position).Magnitude
                if d <= bestDist then best, bestDist = model, d end
            end
        end
    end
    return best, bestDist
end
local function pressAttack(tool)
    if not tool or not tool.Parent or not tool.Enabled then return false end
    -- Tool.Activate is safer for a visible GUI than simulating screen taps.
    local activated = pcall(function() tool:Activate() end)
    -- Some Blox Fruits weapons only listen to mouse/touch input. Executor
    -- mouse1click may work when Tool.Activate is ignored by that weapon.
    -- Avoid clicking GUI buttons accidentally while the hub is open.
    if type(mouse1click) == "function" and hub and not hub.Visible then
        local clicked = pcall(mouse1click)
        return activated or clicked
    end
    return activated
end
local function updateAutoAttack(now)
    if not running or not S.autoAttack then return end
    if now-lastAttack < math.clamp(tonumber(S.attackDelayMs) or 400, 200, 1500)/1000 then return end
    lastAttack = now
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not hum or not root or hum.Health <= 0 or hum.Sit then return end
    local mob, distance = nearbyEnemy(root)
    if not mob then
        if farmStatus and farmStatus.Parent then farmStatus.Text = "Dang cho quai den gan..." end
        return
    end
    local tool = preferredTool(char, hum)
    if not tool then
        if farmStatus and farmStatus.Parent then farmStatus.Text = "Khong tim thay vo / kiem / sung phu hop" end
        return
    end
    pressAttack(tool)
    if farmStatus and farmStatus.Parent then
        farmStatus.Text = string.format("Muc tieu: %s | %.0f studs | %s", mob.Name, distance or 0, tool.Name)
    end
end
on(RunService.Heartbeat:Connect(function()
    if not running then return end
    local now = os.clock()
    local okWater, waterErr = pcall(updateWaterWalk, now)
    if not okWater then warn("[TC Water Walk]", waterErr) end
    local okAttack, attackErr = pcall(updateAutoAttack, now)
    if not okAttack then warn("[TC Auto Attack]", attackErr) end
end))

local function stopAll()
    if not running then return end
    running=false
    removeWaterPlatform()
    restoreCollision()
    for hum in pairs(motionBackup) do restoreMotion(hum) end
    for _,connection in ipairs(connections) do
        pcall(function() connection:Disconnect() end)
    end
    for _,marker in pairs(markers) do clearMarker(marker) end
    table.clear(markers)
    if markerFolder and markerFolder.Parent then markerFolder:Destroy() end
    if screen and screen.Parent then screen:Destroy() end
    if GLOBAL.__TC_ESP_WATCH_STOP==stopAll then
        GLOBAL.__TC_ESP_WATCH_STOP=nil
    end
end
GLOBAL.__TC_ESP_WATCH_STOP=stopAll
on(exit.MouseButton1Click:Connect(stopAll))
on(disableAll.MouseButton1Click:Connect(function()
    S.espIslands=false
    S.espNPC=false
    S.espPlayers=false
    S.espFruits=false
    S.noclip=false
    for _,key in ipairs({"espIslands","noclip"}) do
        if toggleSetters[key] then toggleSetters[key]() end
    end
    saveConfig(true)
    status("Da tat ESP va Noclip",true)
end))

-- Camera resize listeners
local cameraListener
local function bindCamera()
    if cameraListener then cameraListener:Disconnect() end
    local camera=workspace.CurrentCamera
    if camera then
        cameraListener=camera:GetPropertyChangedSignal("ViewportSize"):Connect(rescale)
    end
    rescale()
end
on(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(bindCamera))
bindCamera()

